/*
 * stat-0-double, as a boomerang. It draws itself in, then it is thrown: it flies out on a loop, spinning as a solid in its
 * own plane, curves back and lands where it was drawn, its trail drawing on behind it. Bring the pointer near and it
 * is cocked back. Adapted from the approved stat-1 pilot (dogfood/pilot-boomerang); same depth, 44.7 along -v
 * Generated by dogfood/hard/generate.py from the owner's story (dogfood/HARD.md).
 */
const { icon, spring, stepS, register, pointer, disposer, trace, story, clamp, smooth, lerp, SPRING } = IF;

function mount({ stage, svg, read, src }, reach) {
  const bag = disposer();
  /* the chevron's 45° arms fool the axis measure (it reads an arm as u), so the axes are passed: this drawing's side
     band runs along v, as in every rounded-left view */
  const H = 108, k = H / 220;
  const ic = icon(svg, src, { cx: 176, cy: 168, h: H, u: [0.866, 0.5], v: [-0.88, 0.47] });

  /* inspect.mjs: 0 the chevron's front, 1 a sliver of its top, 2 its side band, 44.7 behind the front along -v (at the
     default placement). It stands upright facing down-left, so it spins in the u-up plane */
  const rang = ic.part("boomerang", [0, 1], { solid: { front: 0, depth: [0, -44.7 * k, 0] } });
  rang.hi(true);
  const home = [rang.rest.cx, rang.rest.cy];
  const trail = trace(svg, { tone: "lo", under: true });

  const life = story(stage, {
    rest: { fly: 0, cock: 0, ink: 1 },
    poster: { fly: 0.35, cock: 0, ink: 1 },
    intro: { dur: 3000, from: { ink: 0 }, ease: "linear" },
    beats: [
      { dur: 900 },
      { dur: 450, to: { cock: 1 } },                     // drawn back
      { dur: 2400, to: { fly: 1, cock: 0 }, ease: "linear" }, // thrown: out, round, back
      { dur: 350, to: { fly: [1.012, 1] }, ease: "out" }, // caught: a small settle
      { dur: 1, to: { fly: 0 } },                       // a whole flight ends where it began
      { dur: 900 },
    ],
  });
  const hand = spring(0, SPRING.hand);
  let max = reach, label = "", path = [];

  /* the flight: one closed loop, out along u, curving away along -v and back along +v, rising a little on the way */
  const at = (p) => [max * Math.sin(Math.PI * p), -0.45 * max * Math.sin(2 * Math.PI * p), 0.25 * max * Math.sin(Math.PI * p)];

  const loop = register(stage, (dt) => {
    const a = life.step(dt), b = stepS(hand, dt);
    const v = life.values(life.held ? { cock: hand.x } : {});
    ic.ink(v.ink);
    const p = clamp(v.fly, 0, 1), [mu, mv, mc] = at(p);
    const back = -6 * v.cock;
    rang.move(mu + back, mv, mc);
    /* two turns in flight, eased in and out with the throw; cocked, it leans back a little */
    const spinDeg = 720 * (p < 1 ? smooth(0, 1, p) : 1) % 360 - 18 * v.cock;
    const o = ic.iso(mu + back, mv, mc);
    rang.spin(Math.abs(spinDeg) < 0.05 ? 0 : spinDeg, [home[0] + o[0], home[1] + o[1]]);
    /* the trail: where it has been this flight, drawing on behind it, gone once it lands */
    if (p > 0.01 && p < 0.999) {
      path = Array.from({ length: 40 }, (_, i) => { const q = at((p * i) / 39), w = ic.iso(q[0], q[1], q[2]); return [home[0] + w[0], home[1] + w[1]]; });
      trail.draw(path, 1);
    } else trail.draw([]);
    const shown = v.ink < 1 ? "drawing" : p > 0.01 && p < 0.999 ? `spin ${Math.round(Math.abs(spinDeg))}°` : v.cock > 0.02 ? "cocked" : "rest";
    if (shown !== label) { read.textContent = shown; label = shown; }
    return a || b;
  });

  const leave = () => { life.hold(false); loop.wake(); };
  bag.add(pointer(stage, {
    move(pt) {
      const near = 1 - smooth(30, 170, Math.hypot(pt[0] - home[0], pt[1] - home[1]));
      if (near <= 0) { leave(); return; }
      if (!life.held) { hand.x = life.values().cock; life.hold(true); }
      hand.t = near;
      loop.wake();
    },
    leave,
  }));

  bag.add(() => { loop.unregister(); while (svg.firstChild) svg.firstChild.remove(); });
  return { set(v) { max = clamp(v, 0, 42); loop.wake(); }, destroy: bag.dispose };
}

isoform({
  name: "stat-0-double",
  icon: "stat-0-double",
  variant: "rounded-left",
  means: "Thrown like a boomerang: it flies out on a loop, spinning as a solid in its own plane, and comes back.",
  rules: [3, 8, 9, 11],
  range: [24, 34, 42],
  mount,
});
